actions:
onPress={() => {
                if (activeChallenge.canClaim) {
                  onChallengeClaim?.(activeChallenge.id);
                } else if (activeChallenge.canStart) {
                  setChallengeConfirmation({ kind: "accept", id: activeChallenge.id, title: activeChallenge.title });
                }
              }}

onPress={() => {
                setChallengeConfirmation({ kind: "cancel", id: activeChallenge.id, title: activeChallenge.title });
              }}

onPress={() => {
                if (isDoneGoal) {
                  Alert.alert(t("goalRepeatTitle"), t("goalRepeatMessage"), [
                    { text: t("goalRepeatCancel"), style: "cancel" },
                    {
                      text: t("goalRepeatAction"),
                      onPress: () => onCreateGoal?.(),
                    },
                  ]);
                  return;
                }
                if (!isActiveGoal) {
                  onSetActiveGoal?.(goalId);
                  return;
                }
                onGoalEdit?.(wish);
              }}

onPress={() => {
                const action = challengeConfirmation;
                setChallengeConfirmation(null);
                if (action?.kind === "cancel") onChallengeCancel?.(action.id);
                else if (action?.kind === "accept") onChallengeAccept?.(action.id);
              }}

onPress={() => {
              if (extendItem && extendOption) onExtend?.(extendItem, { durationMs: extendOption.durationMs, freezeOptionId: extendOption.id, source: "pause_detail" });
              setExtendItemId(null);
            }}

onPress={() => {
            if (pane === "debt" && initialDebtUSD <= 0) {
              openDebtSettings();
              return;
            }
            openTransfer(pane === "debt" ? "debt" : "savings");
          }}

onPress={() =>
                          onThemeToggle(option.id, {
                            proAccentId: option.proAccentId,
                            openAccentPicker: false,
                          })
                        }

onPress={() => {
                  playSound("tap");
                  if (hasSupply) {
                    setTamagotchiSelectedCleanToolId(tool.id);
                    setTamagotchiCleanToolArmed(true);
                    return;
                  }
                  const bought = buyTamagotchiCleanTool(tool.id);
                  if (bought) {
                    setTamagotchiSelectedCleanToolId(tool.id);
                    setTamagotchiCleanToolArmed(true);
                  }
                }}

accessibilityLabel={
                  optionMeta
                    ? t("frequencyReminderCadenceOptionA11y", {
                        cadence: option.label,
                        amount: optionMeta,
                      })
                    : option.label
                }

accessibilityLabel={
        summary
          ? t("frequencyReminderSelectedTime", { time: summary })
          : t("frequencyReminderTimeLabel")
      }
